import glob, json, os
h = "/tmp/tameshi-r18w2-CR49-cHBEBm/cov"
src = open(os.path.join(h, "sources-check.mjs"), encoding="utf-8").read()
lines = src.split("\n")
def off(n):  # UTF-16 offset of the first non-blank char of 1-based line n
    pre = "\n".join(lines[: n - 1]) + ("\n" if n > 1 else "")
    ws = len(lines[n - 1]) - len(lines[n - 1].lstrip())
    return len((pre + lines[n - 1][:ws]).encode("utf-16-le")) // 2
probe = {183: "inspect SOURCES catch", 189: "read SOURCES catch", 251: "ID_DUPLICATE add", 331: "RECHECK_OVERDUE add", 344: "readdirSync knowledge", 349: "readdirSync catch READ_FAILED", 355: "per-entry readFileSync try", 356: "per-entry read catch READ_FAILED (S_FILE_READ anchor)", 368: "entriesWithSource += 1", 483: "DRIFT/CLEAN verdict write", 784: "missingKinds meta-check"}
tot = {n: 0 for n in probe}; procs = 0
for f in sorted(glob.glob(os.path.join(h, "v8", "*.json"))):
    for sc in json.load(open(f))["result"]:
        if not sc["url"].endswith("/cov/sources-check.mjs"):
            continue
        procs += 1
        for n in probe:
            o = off(n); best = None
            for fn in sc["functions"]:
                for r in fn["ranges"]:
                    if r["startOffset"] <= o < r["endOffset"] and (best is None or r["endOffset"] - r["startOffset"] < best[0]):
                        best = (r["endOffset"] - r["startOffset"], r["count"])
            tot[n] += best[1] if best else 0
print("processes_with_target_coverage", procs)
for n, d in probe.items():
    print(f"line {n}: executions={tot[n]}  ({d})  | {lines[n-1].strip()[:90]}")
